DROP TABLE IF EXISTS `error_event`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `error_event` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '错误指纹(归一化堆栈哈希)',
  `env` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'local' COMMENT 'local/dev/staging/prod',
  `service` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上报服务名',
  `message` varchar(1024) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '异常 message',
  `stack` text COLLATE utf8mb4_unicode_ci COMMENT '完整堆栈',
  `context_json` json DEFAULT NULL COMMENT '上下文(版本/host/thread/MDC 等)',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RECEIVED' COMMENT '处理状态: RECEIVED=已入库待处理, ANALYZING=LLM分析中, TICKETED=已建单待通知, NOTIFIED=闭环完成, FAILED=失败(可重试)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_fingerprint` (`fingerprint`),
  KEY `idx_status` (`status`),
  KEY `idx_env_service` (`env`,`service`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=56 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

