DROP TABLE IF EXISTS `internal_ticket`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `internal_ticket` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `event_id` bigint NOT NULL COMMENT '关联 error_event.id',
  `fingerprint` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '错误指纹(同指纹复用工单)',
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工单标题',
  `status` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'OPEN' COMMENT 'OPEN/IN_PROGRESS/RESOLVED/CLOSED/IGNORED',
  `priority` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'P2' COMMENT 'P0/P1/P2/P3',
  `assignee` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '处理人',
  `resolution` text COLLATE utf8mb4_unicode_ci COMMENT '解决方案(RESOLVED 时填写)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `resolved_at` datetime DEFAULT NULL COMMENT '解决时间',
  `closed_at` datetime DEFAULT NULL COMMENT '关闭时间',
  PRIMARY KEY (`id`),
  KEY `idx_event_id` (`event_id`),
  KEY `idx_fingerprint` (`fingerprint`),
  KEY `idx_status` (`status`),
  KEY `idx_assignee` (`assignee`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

